INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_1151', 'mbe', '1151', '891', '1998', 'EVIDENCE', '158', '', 'Defendant was charged with attempted murder of Victor in a sniping incident in which Defendant allegedly shot at Victor from ambush as Victor drove his car along an expressway. The prosecutor offers evidence that seven years earlier Defendant had fired a shotgun into a woman''s home and that Defendant had once pointed a handgun at another driver while driving on the street. This evidence should be', 'excluded, because such evidence can be elicited only during cross-examination.', 'excluded, because it is improper character evidence.', 'admitted as evidence of Defendant''s propensity toward violence.', 'admitted as relevant evidence of Defendant''s identity, plan, or motive.', 'B', 'Generally, character evidence is neither relevant nor admissible.', 'mbe_874', 0, '158'),
('mbe_1152', 'mbe', '1152', '892', '1998', 'REAL PROP.', '159', '', 'Art, who owned Blackacre in fee simple, conveyed Blackacre to Bea by warranty deed. Celia, an adjoining owner, asserted title to Blackacre and brought an appropriate action against Bea to quiet title to Blackacre. Bea demanded that Art defend Bea''s title under the deed''s covenant of warranty, but Art refused. Bea then successfully defended at her own expense. Bea brought an appropriate action against Art to recover Bea''s expenses incurred in defending against Celia''s action to quiet title to Blackacre. In this action, the court should decide for', 'Bea, because in effect it was Art''s title that was challenged.', 'Bea, because Art''s deed to her included the covenant of warranty.', 'Art, because the title Art conveyed was not defective.', 'Art, because Celia may elect which of Art or Bea to sue.', 'C', '“A warranty deed is a deed in which the grantor warrants good clear title.
  The usual covenants of title are warranties of seisen, quiet enjoyment, right to convey, freedom from encumbrances, and defense of title as to all claims.” Windell v. Miller, 687 N.E.2d 585, 588 (Ind.Ct.App.1997) (citation omitted).', 'mbe_875', 0, '159'),
('mbe_1153', 'mbe', '1153', '893', '1998', 'CONST. LAW', '160', '', 'Alex contracted for expensive cable television service for a period of six months solely to view the televised trial of Clark, who was on trial for murder in a court of the state of Green. In the midst of the trial, the judge prohibited any further televising of Clark''s trial because he concluded that the presence of television cameras was disruptive. Alex brought an action in a federal district court against the judge in Clark''s case asking only for an injunction that would require the judge to resume the televising of Clark''s trial. Alex alleged that the judge''s order to stop the televising of Clark''s trial deprived him of property-his investment in cable television service-without due process of law. Before Alex''s case came to trial, Clark''s criminal trial concluded in a conviction and sentencing. There do not appear to be any obvious errors in the proceeding that led to the result in Clark''s case. After Clark''s conviction and sentencing, the defendant in Alex''s case moved to dismiss that suit. The most proper disposition of this motion by the federal court would be to', 'defer action on the motion until after any appellate proceedings in Clark''s case have concluded, because Clark might appeal, his conviction might be set aside, he might be tried again, and television cameras might be barred from the new trial.', 'defer action on the motion until after the Green Supreme Court expresses a view on its proper disposition, because the state law of mootness governs suits in federal court when the federal case is inexorably intertwined with a state proceeding.', 'grant the motion, because the subject matter of the controversy between Alex and the defendant has ceased to exist and there is no strong likelihood that it will be revived.', 'deny the motion, because Alex has raised an important constitutional question- whether his investment in cable service solely to view Clark''s trial is property protected by the due process clause of the Fourteenth Amendment.', 'C', 'Mootness is the ground for dismissal of a lawsuit based on the lack of a live controversy (Environmental Conservation Org. v. City of Dallas, 529 F.3d 519, 527 (5th Cir. 2008)). A court has the authority to decide only cases that present a live controversy (U.S. Const., art. III, § 2, cl. 1). A lawsuit becomes moot when the parties either:
Do not have sufficient legal interests in the litigation to maintain it.
Lose a legally cognizable interest in the outcome of the litigation.
(In re Scruggs, 392 F.3d 124, 128 (5th Cir. 2004).)', 'mbe_876', 0, '160'),
('mbe_1154', 'mbe', '1154', '894', '1998', 'TORTS', '161', '', 'Traveler was a passenger on a commercial aircraft owned and operated by Airline. The aircraft crashed into a mountain, killing everyone on board. The flying weather was good. Traveler''s legal representative brought a wrongful death action against Airline. At trial, the legal representative offered no expert or other testimony as to the cause of the crash. On Airline''s motion to dismiss at the conclusion of the legal representative''s case, the court should', 'grant the motion, because the legal representative has offered no evidence as to the cause of the crash.', 'grant the motion, because the legal representative has failed to offer evidence negating the possibility that the crash may have been caused by mechanical failure that Airline could not have prevented.', 'deny the motion, because the jury may infer that the aircraft crashed due to Airline''s negligence.', 'deny the motion, because in the circumstances common carriers are strictly liable.', 'C', 'In order to prevail on a claim for wrongful death, the plaintiff must prove: “(1) a wrongful act, neglect, or default of the defendant that proximately caused the death and that would have entitled the decedent to maintain an action and recover damages if death had not ensued; (2) the decedent was survived by a spouse, children, parents, or other next of kin; and (3) the survivors suffered damages by reasons of the wrongful death.” Cline v. Stein, 9th Dist. Wayne No. 13CA0052, 2015-Ohio-2979, 2015 WL 4511295, ¶ 30, quoting McDowell v. DeCarlo, 9th Dist. Summit No. 23376, 2007-Ohio-1262, 2007 WL 841040, ¶ 34.', 'mbe_877', 0, '161'),
('mbe_1155', 'mbe', '1155', '895', '1998', 'CONST. LAW', '162', '', 'Company wanted to expand the size of the building it owned that housed Company''s supermarket by adding space for a coffeehouse. Company''s building was located in the center of five acres of land owned by Company and devoted wholly to parking for its supermarket customers. City officials refused to grant a required building permit for the coffeehouse addition unless Company established in its store a child care center that would take up space at least equal to the size of the proposed coffeehouse addition, which was to be 20% of the existing building. This action of City officials was authorized by provisions of the applicable zoning ordinance. In a suit filed in state court against appropriate officials of City, Company challenged this child care center requirement solely on constitutional grounds. The lower court upheld the requirement even though City officials presented no evidence and made no findings to justify it other than a general assertion that there was a shortage of child care facilities in City. Company appealed. The court hearing the appeal should hold that the requirement imposed by City on the issuance of this building permit is', 'constitutional, because the burden was on Company to demonstrate that there was no rational relationship between this requirement and a legitimate governmental interest, and Company could not do so because the requirement is reasonably related to improving the lives of families and children residing in City.', 'constitutional, because the burden was on Company to demonstrate that this requirement was not necessary to vindicate a compelling governmental interest, and Company could not do so on these facts.', 'unconstitutional, because the burden was on City to demonstrate that this requirement was necessary to vindicate a compelling governmental interest, and City failed to meet its burden under that standard.', 'unconstitutional, because the burden was on City to demonstrate a rough proportionality between this requirement and the impact of Company''s proposed action on the community, and City failed to do so.', 'D', '"“Rough proportionality” test applied in determining whether degree of exactions required by city''s building permit conditions bore required relationship to projected impact on proposed development to satisfy takings clause of Fifth Amendment; no precise mathematical calculation was required, but city was required to make some sort of individualized determination that required dedication was related both in nature and extent to impact of proposed development.', 'mbe_878', 0, '162'),
('mbe_1156', 'mbe', '1156', '896', '1998', 'REAL PROP.', '163', '', 'Ollie owned a large tract of land known as Peterhill. During Ollie''s lifetime, Ollie conveyed the easterly half (East Peterhill), situated in the municipality of Hawthorn, to Abel, and the westerly half (West Peterhill), situated in the municipality of Sycamore, to Betty. Each of the conveyances, which were promptly and properly recorded, contained the following language: The parties agree for themselves and their heirs and assigns that the premises herein conveyed shall be used only for residential purposes; that each lot created within the premises herein conveyed shall contain not less than five acres; and that each lot shall have not more than one single-family dwelling. This agreement shall bind all successor owners of all or any portion of Peterhill and any owner of any part of Peterhill may enforce this covenant. After Ollie''s death, Abel desired to build houses on one-half acre lots in the East Peterhill tract as authorized by current applicable zoning and building codes in Hawthorn. The area surrounding East Peterhill in Hawthorn was developed as a residential community with homes built on one-half acre lots. West Peterhill was in a residential area covered by the Sycamore zoning code, which allowed residential development only on five-acre tracts of land. In an appropriate action brought by Betty to enjoin Abel''s proposed construction on one- half acre lots, the court will find the quoted restriction to be', 'invalid, because of the change of circumstance in the neighborhood.', 'invalid, because it conflicts with the applicable zoning code.', 'valid, but only so long as the original grantees from Ollie own their respective tracts of Peterhill.', 'valid, because the provision imposed an equitable servitude.', 'D', 'Thus, an equitable servitude by estoppel may be created as the result of (1) either an express or implied representation made under circumstances where (2) it is reasonably foreseeable that the person to whom the representation is made will rely on it, (3) that person does so rely, (4) such reliance is reasonable, and (5) the establishment of a servitude is necessary to avoid injustice.', 'mbe_879', 0, '163'),
('mbe_1157', 'mbe', '1157', '897', '1998', 'EVIDENCE', '164', '', 'At Defendant''s murder trial, Defendant calls Witness as his first witness to testify that Defendant has a reputation in their community as a peaceable and truthful person. The prosecutor objects on the ground that Witness''s testimony would constitute improper character evidence. The court should', 'admit the testimony as to peaceableness, but exclude the testimony as to truthfulness.', 'admit the testimony as to truthfulness, but exclude the testimony as to peaceableness.', 'admit the testimony as to both character traits.', 'exclude the testimony as to both character traits.', 'A', 'there are circumstances in which evidence of a person''s character may be admitted to prove that he acted in conformity therewith on a particular occasion. In the specific situations enumerated, character evidence is admissible in direct contravention of the general principle that character evidence is not admissible to prove conduct.', 'mbe_880', 0, '164'),
('mbe_1158', 'mbe', '1158', '898', '1998', 'CONST. LAW', '165', '', 'The governor of the state of Green proposes to place a Christmas nativity scene, the components of which would be permanently donated to the state by private citizens, in the Green Capitol Building rotunda where the Green Legislature meets annually. The governor further proposes to display this state- owned nativity scene annually from December 1 to December 31, next to permanent displays that depict the various products manufactured in Green. The governor''s proposal is supported by all members of both houses of the legislature. If challenged in a lawsuit on establishment clause grounds, the proposed nativity scene display would be held', 'unconstitutional, because the components of the nativity scene would be owned by the state rather than by private persons.', 'unconstitutional, because the nativity scene would not be displayed in a context that appeared to depict and commemorate the Christmas season as a primarily secular holiday.', 'constitutional, because the components of the nativity scene would be donated to the state by private citizens rather than purchased with state funds.', 'constitutional, because the nativity scene would be displayed alongside an exhibit of various products manufactured in Green.', 'B', 'In this case, the focus of our inquiry must be on the crèche in the context of the Christmas season. See, e.g., Stone v. Graham, 449 U.S. 39, 101 S.Ct. 192, 66 L.Ed.2d 199 (1980) (per curiam ); Abington School District v. Schempp, supra. In Stone, for example, we invalidated a state statute requiring the posting of a copy of the Ten Commandments on public classroom walls. But the Court carefully pointed out that the Commandments were posted purely as a religious admonition, not “integrated into the school curriculum, where the Bible may constitutionally be used in an appropriate study of history, civilization, ethics, comparative religion, or the like.” 449 U.S., at 42, 101 S.Ct., at 194. Similarly, in Abington, although the Court struck down the practices in two States requiring daily Bible readings in public schools, it specifically noted that nothing in the Court''s holding was intended to “indicat[e] that such study of the Bible or of religion, when presented objectively as part of a secular program of education, may not be effected consistently *680 with the First Amendment.” 374 U.S., at 225, 83 S.Ct., at 1573. Focus exclusively on the religious component of any activity would inevitably lead to its invalidation under the Establishment Clause.
The Court has invalidated legislation or governmental action on the ground that a secular purpose was lacking, but only when it has concluded there was no question that the statute or activity was motivated wholly by religious considerations. See, e.g., Stone v. Graham, supra, 449 U.S., at 41, 101 S.Ct., at 193; Epperson v. Arkansas, 393 U.S. 97, 107–109, 89 S.Ct. 266, 272–273, 21 L.Ed.2d 228 (1968); Abington School District v. Schempp, supra, 374 U.S., at 223–224, 83 S.Ct., at 1572; Engel v. Vitale, 370 U.S. 421, 424–425, 82 S.Ct. 1261, 1263–1264, 8 L.Ed.2d 601 (1962). Even where the benefits to religion were substantial, as in Everson, supra; Board of Education v. Allen, 392 U.S. 236, 88 S.Ct. 1923, 20 L.Ed.2d 1060 (1968), Walz, supra, and Tilton, supra, we saw a secular purpose and no conflict with the Establishment Clause. Cf. Larkin v. Grendel''s Den, 459 U.S. 116, 103 S.Ct. 505, 74 L.Ed.2d 297 (1982).
The District Court inferred from the religious nature of the crèche that the City has no secular purpose for the display. In so doing, it rejected the City''s claim that its reasons for including the crèche are essentially the same as its reasons for sponsoring the display as a whole. The District Court plainly erred by focusing almost exclusively on the crèche. When viewed in the proper context of the Christmas Holiday season, it is apparent that, on this record, there is insufficient evidence to establish that the inclusion of the crèche is a purposeful or surreptitious effort to express some kind of subtle governmental advocacy of a particular religious message. In a pluralistic society a variety of motives and purposes are implicated. The City, like the Congresses and Presidents, however, has principally taken note of a significant historical religious event long celebrated in the Western World. The crèche in the display depicts the historical origins of this traditional event long recognized as a National Holiday. See *681 Allen v. Hickel, 424 F.2d 944 (CADC 1970); Citizens Concerned for Separation of Church and State v. City and County of Denver, 526 F.Supp. 1310 (D Colo.1981).
The narrow question is whether there is a secular purpose for Pawtucket''s display of the crèche. The display is sponsored by the City to celebrate the Holiday and to depict the origins of that Holiday. These are legitimate secular purposes. The District Court''s inference, drawn from the religious nature of the crèche, that the City has no secular purpose was, on this record, clearly erroneous.
The District Court found that the primary effect of including the crèche is to confer a substantial and impermissible benefit on religion in general and on the Christian faith in particular. Comparisons of the relative benefits to religion of different forms of governmental support are elusive and difficult to make. But to conclude that the primary effect of including the crèche is to advance religion in violation of the Establishment Clause would require that we view it as more beneficial to and more an endorsement of religion, for example, than expenditure of large sums of public money for textbooks supplied throughout the country to students attending church-sponsored schools, Board of Education v. Allen, supra; expenditure of public funds for transportation of *682 students to church-sponsored schools, Everson v. Board of Education, supra; federal grants for college buildings of church-sponsored institutions of higher education combining secular and religious education, Tilton, supra; noncategorical grants to church-sponsored colleges and universities, Roemer v. Board of Public Works, 426 U.S. 736, 96 S.Ct. 2337, 49 L.Ed.2d 179 (1976); and the tax exemptions for church properties sanctioned in Walz, supra. It would also require that we view it as more of an endorsement of religion than the Sunday Closing Laws upheld in McGowan v. Maryland, 366 U.S. 420, 81 S.Ct. 1101, 6 L.Ed.2d 393 (1961); the release time program for religious training in Zorach, supra; and the legislative prayers upheld in Marsh, supra.
We are unable to discern a greater aid to religion deriving from inclusion of the crèche than from these benefits and endorsements previously held not violative of the Establishment Clause. What was said about the legislative prayers in Marsh, supra, 463 U.S., at ––––, 103 S.Ct., at 3336, and implied about the Sunday Closing Laws in McGowan is true of the City''s inclusion of the crèche: its “reason or effect merely happens to coincide or harmonize with the tenets of some ... religions.” See McGowan, supra, 366 U.S., at 442, 81 S.Ct., at 1113.', 'mbe_881', 0, '165'),
('mbe_1159', 'mbe', '1159', '899', '1998', 'CRIM. LAW', '166', '', 'Two police officers in uniform were on foot patrol in a neighborhood frequented by drug sellers. They saw Sandra, who, when she saw them, turned around and started to walk quickly away. The police ran after her and shouted, "Stop and don''t take another step, lady!" Sandra turned, looked at the police, and stopped. She put her arms up in the air. As the police approached, she threw a small object into nearby bushes. The police retrieved the object, which turned out to be a small bag of cocaine, and then arrested Sandra. Sandra is charged with possession of the cocaine. She moves pretrial to suppress its use as evidence on the ground that it was obtained as the result of an illegal search and seizure. Her motion should be', 'granted, because the police did not know the item was cocaine until after they had seized it.', 'granted, because the police acquired the cocaine as the result of an unlawful seizure.', 'denied, because the police had probable cause to seize the package.', 'denied, because Sandra voluntarily discarded the contraband.', 'B', 'Bootstrapping evidence found in a search “incident to arrest”—based on probable cause for only a minor violation that would otherwise not result in an arrest—so that the fruits of a search incident to arrest themselves provide the justification for the arrest, is not permissible. See Smith v. Ohio, 494 U.S. 541, 543, 110 S.Ct. 1288, 108 L.Ed.2d 464 (1990) (“[I]t is axiomatic that an incident search may not precede an arrest and serve as part of its justification.”) (internal quotation marks and citation omitted); United States v. Donaldson, 793 F.2d 498, 503 (2d Cir.1986) (“To be sure, care must be taken to avoid bootstrapping that allows the fruits of a search incident to an arrest to provide the basis for the arrest.”); United States v. Friedman, No. 95–CR–192, 1996 WL 612456, at *15 (E.D.N.Y. June 25, 1996) (finding that case in which three men arrested for possession of firearms after being stopped for traffic violations, who were only arrested following a search of the car and discovery of the firearms, “presents a danger of ‘bootstrapping’ that is not present in cases such as Donaldson ”) aff''d in part, rev''d in part, 300 F.3d 111 (2d Cir.2002) and aff''d, 43 Fed.Appx. 424 (2d Cir.2002).', 'mbe_882', 0, '166'),
('mbe_1160', 'mbe', '1160', '900', '1998', 'EVIDENCE', '167', '', 'In a federal civil trial, Plaintiff wishes to establish that, in a state court, Defendant had been convicted of fraud, a fact that Defendant denies. Which mode of proof of the conviction is LEAST likely to be permitted?', 'A certified copy of the judgment of conviction, offered as a self- authenticating document.', 'Testimony of Plaintiff, who was present at the time of the sentence.', 'Testimony by a witness to whom Defendant made an oral admission that he had been convicted.', 'Judicial notice of the conviction, based on the court''s telephone call to the clerk of the state court, whom the judge knows personally.', 'D', 'A party is entitled upon timely request to an opportunity to be heard as to the propriety of taking judicial notice. Pa. R.E. 201(e); see Commonwealth v. Covert, 322 Pa.Super. 192, 469 A.2d 248, 251 (1983) ( “judicial notice should not serve to deny the opposing party the chance to disprove the fact sought to be judicially noticed”). Judicial notice itself does not necessarily establish a fact. In Interest of D.S., 424 Pa.Super. 350, 622 A.2d 954 (1993).  Judicial notice of a fact, when correctly taken, constitutes evidence, which like any evidence, may be rebutted. Id.', 'mbe_883', 0, '167'),
('mbe_1161', 'mbe', '1161', '901', '1998', 'REAL PROP.', '168', '', 'Three years ago Adam conveyed Blackacre to Betty for $50,000 by a deed that provided: "By accepting this deed, Betty covenants for herself, her heirs and assigns, that the premises herein conveyed shall be used solely for residential purposes and, if the premises are used for nonresidential purposes, Adam, his heirs and assigns, shall have the right to repurchase the premises for the sum of one thousand dollars ($1,000)." In order to pay the $50,000 purchase price for Blackacre, Betty obtained a $35,000 mortgage loan from the bank. Adam had full knowledge of the mortgage transaction. The deed and mortgage were promptly and properly recorded in proper sequence. The mortgage, however, made no reference to the quoted language in the deed. Two years ago Betty converted her use of Blackacre from residential to commercial without the knowledge or consent of Adam or of the bank. Betty''s commercial venture failed, and Betty defaulted on her mortgage payments to the bank. Blackacre now has a fair market value of $25,000. The bank began appropriate foreclosure proceedings against Betty. Adam properly intervened, tendered $1,000, and sought judgment that Betty and the bank be ordered to convey Blackacre to Adam, free and clear of the mortgage. The common-law Rule Against Perpetuities is unmodified by statute. If the court rules against Adam, it will be because', 'the provision quoted from the deed violates the Rule Against Perpetuities.', 'the Bank had no actual knowledge of, and did not consent to, the violation of the covenant.', 'the rights reserved by Adam were subordinated, by necessary implication, to the rights of the bank as the lender of the purchase money.', 'the consideration of $1,000 was inadequate.', 'A', 'The rule against perpetuities is generally stated with deceptive simplicity as follows: “No interest is good unless it must vest, if at all, not later than twenty-one years after some life in being at the creation of the interest.” Iglehart v. Phillips, 383 So.2d 610, 614 (Fla.1980) (quoting John Chipman Gray, The Rule Against Perpetuities, § 201 (4th ed.1942)).', 'mbe_884', 0, '168'),
('mbe_1162', 'mbe', '1162', '902', '1998', 'CONTRACTS', '169', '', 'Loyal, aged 60, who had no plans for early retirement, had worked for Mutate, Inc., for 20 years as a managerial employee-at-will when he had a conversation with the company''s president, George Mutant, about Loyal''s post- retirement goal of extensive travel around the United States. A month later, Mutant handed Loyal a written, signed resolution of the company''s Board of Directors stating that when and if Loyal should decide to retire, at his option, the company, in recognition of his past service, would pay him a $2,000- per-month lifetime pension. (The company had no regularized retirement plan for at- will employees.) Shortly thereafter, Loyal retired and immediately bought a $30,000 recreational vehicle for his planned travels. After receiving the promised $2,000 monthly pension from Mutate, Inc., for six months, Loyal, now unemployable elsewhere, received a letter from Mutate, Inc., advising him that the pension would cease immediately because of recessionary budget constraints affecting in varying degrees all managerial salaries and retirement pensions. In a suit against Mutate, Inc., for breach of contract, Loyal will probably', 'win, because he retired from the company as bargained-for consideration for the Board''s promise to him of a lifetime pension.', 'win, because he timed his decision to retire and to buy the recreational vehicle in reasonable reliance on the Board''s promise to him of a lifetime pension.', 'lose, because the Board''s promise to him of a lifetime pension was an unenforceable gift promise.', 'lose, because he had been an employee- at-will throughout his active service with the company.', 'B', 'In Foremost, this Court discussed reasonable reliance in light of this Court''s formulation of that standard in Torres v. State Farm Fire & Cas. Co., 438 So.2d 757, 759 (Ala.1983):
“If the circumstances are such that a reasonably prudent person who exercised ordinary care would have discovered the true facts, the plaintiffs should not recover.”
(Citing Bedwell Lumber Co. v. T & T Corp., 386 So.2d 413, 415 (Ala.1980).)', 'mbe_885', 0, '169'),
('mbe_1163', 'mbe', '1163', '903', '1998', 'CONST. LAW', '170', '', 'Congress wishes to enact legislation prohibiting discrimination in the sale or rental of housing on the basis of the affectional preference or sexual orientation of the potential purchaser or renter. Congress wishes this statute to apply to all public and private vendors and lessors of residential property in this country, with a few narrowly drawn exceptions. The most credible argument for congressional authority to enact such a statute would be based upon the', 'general welfare clause of Article I, Section 8, because the conduct the statute prohibits could reasonably be deemed to be harmful to the national interest.', 'commerce clause of Article I, Section 8, because, in inseverable aggregates, the sale or rental of almost all housing in this country could reasonably be deemed to have a substantial effect on interstate commerce.', 'enforcement clause of the Thirteenth Amendment, because that amendment clearly prohibits discrimination against the class of persons protected by this statute.', 'enforcement clause of the Fourteenth Amendment, because that amendment prohibits all public and private actors from engaging in irrational discrimination.', 'B', 'Consistent with this structure, we have identified three broad categories of activity that Congress may regulate under its commerce power. Perez, supra, at 150, 91 S.Ct., at 1359; see also Hodel, supra, at 276–277, 101 S.Ct., at 2360–2361. First, Congress may regulate the use of the channels of interstate commerce. See, e.g., Darby, 312 U.S., at 114, 61 S.Ct., at 457; Heart of Atlanta Motel, supra, at 256, 85 S.Ct., at 357 (“ ‘[T]he authority of Congress to keep the channels of interstate commerce free from immoral and injurious uses has been frequently sustained, and is no longer open to question.’ ” (quoting Caminetti v. United States, 242 U.S. 470, 491, 37 S.Ct. 192, 197, 61 L.Ed. 442 (1917))). Second, Congress is empowered to regulate and protect the instrumentalities of interstate commerce, or persons or things in interstate commerce, even though the threat may come only from intrastate activities. See, e.g., Shreveport Rate Cases, 234 U.S. 342, 34 S.Ct. 833, 58 L.Ed. 1341 (1914); Southern R. Co. v. United States, 222 U.S. 20, 32 S.Ct. 2, 56 L.Ed. 72 (1911) (upholding amendments to Safety Appliance Act as applied to vehicles used in intrastate commerce); Perez, supra, at 150, 91 S.Ct., at 1359 (“[F]or example, the destruction of an aircraft (18 U.S.C. § 32), or ... thefts from interstate shipments (18 U.S.C. § 659)”). Finally, Congress'' commerce authority includes the power to regulate those activities *559 having a substantial **1630 relation to interstate commerce, Jones & Laughlin Steel, 301 U.S., at 37, 57 S.Ct., at 624, i.e., those activities that substantially affect interstate commerce, Wirtz, supra, at 196, n. 27, 88 S.Ct., at 2024, n. 27.', 'mbe_886', 0, '170'),
('mbe_1164', 'mbe', '1164', '904', '1998', 'TORTS', '171', '', 'Because of Farmer''s default on his loan, the bank foreclosed on the farm and equipment that secured the loan. Among the items sold at the resulting auction was a new tractor recently delivered to Farmer by the retailer. Shortly after purchasing the tractor at the auction, Pratt was negligently operating the tractor on a hill when it rolled over due to a defect in the tractor''s design. He was injured as a result. Pratt sued the auctioneer, alleging strict liability in tort. The jurisdiction has not adopted a comparative fault rule in strict liability cases. In this suit, the result should be for the', 'plaintiff, because the defendant sold a defective product that injured the plaintiff.', 'plaintiff, if the defendant failed to inspect the tractor for defects prior to sale.', 'defendant, because he should not be considered a "seller" for purposes of strict liability in tort.', 'defendant, because the accident was caused in part by Pratt''s negligence.', 'C', 'Strict liability means liability without proof that the defendant was negligent, i.e., that the defendant failed to take reasonable steps to prevent a foreseeable harm. Caporale v. C.W. Blakeslee & Sons, Inc., 149 Conn. 79, 83, 175 A.2d 561 (1961) (defendant subject to strict liability can be held liable “even though he uses all proper care” [internal quotation marks omitted] )', 'mbe_887', 0, '171'),
('mbe_1166', 'mbe', '1166', '906', '1998', 'EVIDENCE', '173', '', 'Plaintiff sued Defendant for injuries sustained in an automobile collision. During Plaintiffs hospital stay, Doctor, a staff physician, examined Plaintiffs X rays and said to Plaintiff, "You have a fracture of two vertebrae, C4 and C5." Intern, who was accompanying Doctor on her rounds, immediately wrote the diagnosis on Plaintiff''s hospital record. At trial, the hospital records custodian testifies that Plaintiff''s hospital record was made and kept in the ordinary course of the hospital''s business. The entry reporting Doctor''s diagnosis is', 'inadmissible, because no foundation has been laid for Doctor''s competence as an expert.', 'inadmissible, because Doctor''s opinion is based upon data that are not in evidence.', 'admissible as a statement of then existing physical condition.', 'admissible as a record of regularly conducted business activity.', 'D', 'A memorandum, report, record, or data compilation, in any form, of acts, events, conditions, opinions, or diagnoses, made at or near the time by, or from information transmitted by, a person with knowledge, if
(i) kept in the course of a regularly conducted business activity and
(ii) it was the regular practice of that business activity to make the memorandum, report, record, or data compilation,
all as shown by the testimony of the custodian or other qualified witness, or by affidavit or by document under seal under Rule 902 of the Rules of Evidence made by the custodian or witness, unless the source of information or the method or circumstances of preparation indicate lack of trustworthiness.
Authentication of evidence by affidavit shall be confined to the records of nonparties, and the proponent of that evidence shall give advance notice to all other parties of intent to offer the evidence with authentication by affidavit.
The term "business" as used in this paragraph includes business, institution, association, profession, occupation, and calling of every kind, whether or not conducted for profit.', 'mbe_888', 0, '173'),
('mbe_1168', 'mbe', '1168', '908', '1998', 'REAL PROP.', '175', '', 'Adam owns Townacres in fee simple, and Bess owns the adjoining Greenacres in fee simple. Adam has kept the lawns and trees on Townacres trimmed and neat. Bess "lets nature take its course" at Greenacres. The result on Greenacres is a tangle of underbrush, fallen trees, and standing trees that are in danger of losing limbs. Many of the trees on Greenacres are near Townacres. In the past, debris and large limbs have been blown from Greenacres onto Townacres. By local standards Greenacres is an eyesore that depresses market values of real property in the vicinity, but the condition of Greenacres violates no applicable laws or ordinances. Adam demanded that Bess keep the trees near Townacres trimmed. Bess refused. Adam brought an appropriate action against Bess to require Bess to abate what Adam alleges to be a nuisance. In the lawsuit, the only issue is whether the condition of Greenacres constitutes a nuisance. The strongest argument that Adam can present is that the condition of Greenacres', 'has an adverse impact on real estate values.', 'poses a danger to the occupants of Townacres.', 'violates community aesthetic standards.', 'cannot otherwise be challenged under any law or ordinance.', 'B', 'To support their claim of private nuisance, plaintiffs were required to show that (1) defendants interfered with the use or enjoyment of their property rights and privileges; (2) defendants'' invasion of those property interests caused plaintiffs significant harm; and (3) the invasion was either intentional and unreasonable or otherwise “actionable under the rules governing liability for negligent, reckless, or ultrahazardous conduct.” Capitol Properties Group, LLC v. 1247 Ctr St, LLC, 283 Mich. App. 422, 431-432; 770 N.W.2d 105 (2009).', 'mbe_889', 0, '175'),
('mbe_1169', 'mbe', '1169', '909', '1998', 'CONTRACTS', '176', '', 'Breeder bought a two-month-old registered boar at auction from Pigstyle for $800. No express warranty was made. Fifteen months later, tests by experts proved conclusively that the boar had been born incurably sterile. If this had been known at the time of the sale, the boar would have been worth no more than $100. In an action by Breeder against Pigstyle to avoid the contract and recover the price paid, the parties stipulate that, as both were and had been aware, the minimum age at which the fertility of a boar can be determined is about 12 months. Which of the following will the court probably decide?', 'Breeder wins, because the parties were mutually mistaken as to the boar''s fertility when they made the agreement.', 'Breeder wins, because Pigstyle impliedly warranted that the boar was fit for breeding.', 'Pigstyle wins, because Breeder assumed the risk of the boar''s sterility.', 'Pigstyle wins, because any mistake involved was unilateral, not mutual.', 'C', 'The caveat emptor doctrine is equally inapplicable, at least at this stage of the case. Meaning “let the buyer beware,” caveat emptor “places the duty to examine and judge the value and condition of the property solely on the buyer and protects the seller from liability for any defects.” Transcapital Bank v. Shadowbrook at Vero, LLC, 226 So. 3d 856, 862 (Fla. 4th DCA 2017) (quoting Turnberry Court Corp. v. Bellini, 962 So. 2d 1006, 1007 (Fla. 3d DCA 2007)). Three exceptions to this doctrine exist: “1) where some artifice or trick has been employed to prevent the purchaser from making independent inquiry; 2) where the other party does not have equal opportunity to become apprised of the fact; and, 3) where a party undertakes to disclose facts and fails to disclose the whole truth.” Id. (quoting Green Acres, Inc. v. First Union Nat''l Bank of Fla., 637 So. 2d 363, 364 (Fla. 4th DCA 1994)). Monroe''s affidavit raises all three exceptions.', 'mbe_890', 0, '176'),
('mbe_1170', 'mbe', '1170', '910', '1998', 'TORTS', '177', '', 'Homeowner owns a house on a lake. Neighbor owns a house across a driveway from Homeowner''s property. Neighbor''s house sits on a hill and Neighbor can see the lake from his living room window. Homeowner and Neighbor got into an argument and Homeowner erected a large spotlight on his property that automatically comes on at dusk and goes off at sunrise. The only reason Homeowner installed the light was to annoy Neighbor. The glare from the light severely detracts from Neighbor''s view of the lake. In a suit by Neighbor against Homeowner, will Neighbor prevail?', 'Yes, because Homeowner installed the light solely to annoy Neighbor.', 'Yes, if, and only if, Neighbor''s property value is adversely affected.', 'No, because Neighbor''s view of the lake is not always obstructed.', 'No, if the spotlight provides added security to Homeowner''s property.', 'A', 'Based on general principles of nuisance law, and decisions from other jurisdictions, we conclude that a sustained and intentional campaign to annoy a neighbor by interfering with the use and enjoyment of the neighbor''s property can amount to a private nuisance. Affording the trial court''s decision denying the Joneses’ motion for a new trial all presumptive support, we conclude that the trial court did not abuse its discretion because there was legally sufficient evidence for a jury to find that the Joneses’ conduct amounted to a private nuisance on the basis that they engaged in a sustained and intentional campaign to annoy and harass Hart', 'mbe_891', 0, '177'),
('mbe_1171', 'mbe', '1171', '911', '1998', 'CRIM. LAW', '178', '', 'On May 1, 1987, a car driven by Debra struck Peggy, a pedestrian. On July 1, 1987, with regard to this incident, Debra pleaded guilty to reckless driving (a misdemeanor) and was sentenced to 30 days in jail and a fine of $1,000. She served the sentence and paid the fine. On April 1, 1988, Peggy died as a result of the injuries she suffered in the accident. On March 1, 1991, a grand jury indicted Debra on a charge of manslaughter of Peggy. On May 15, 1991, trial had not begun and Debra filed a motion to dismiss the indictment on the ground of double jeopardy in that her conviction of reckless driving arose out of the same incident, and on the ground that the three-year statute of limitations for manslaughter had run. Debra''s motion should be', 'granted only on double jeopardy grounds.', 'granted only on statute of limitations grounds.', 'granted on either double jeopardy grounds or statute of limitations grounds.', 'denied on both grounds.', 'D', 'The court in Wilson stated: “The law upon this subject is well settled in its application to cases where the defendant has committed an act of violence which in its immediate result amounts to a misdemeanor, but which in its after consequences upon the victim of the violent act becomes, through the death of that victim, murder or manslaughter. In such an event the second prosecution is not for the same offense as the first; and the reason for this is, as is well stated in Wharton on Criminal Pleading and Practice, ninth edition, section 476, ‘that as at the time of conviction of assault there could have been no conviction of the homicide the prosecution of the homicide is not barred by the conviction of the assault.’ [Citation.] ... In none of the cases cited by the appellant in support of his contention as to his plea of ‘once in jeopardy’ does the element of death, which is the essential basis of the charge of manslaughter, appear to be present; nor upon principle do we think a case can be conceived wherein a charge of murder or manslaughter should be defeated by a plea of once in jeopardy based upon a mere misdemeanor *662 charge, trial, or conviction of the assault or offense which had later resulted in the death of the injured victim.” (Id., 193 Cal. at p. 515, 226 p. 5.)', 'mbe_892', 0, '178'),
('mbe_1173', 'mbe', '1173', '913', '1998', 'CONST. LAW', '180', '', 'State Y has a state employee grievance system that requires any state employee who wishes to file a grievance against the state to submit that grievance for final resolution to a panel of three arbitrators chosen by the parties from a statewide board of 13 arbitrators. In any given case, the grievant and the state alternate in exercising the right of each party to eliminate five members of the board, leaving a panel of three members to decide their case. At the present time, the full board is composed of seven male arbitrators and six female arbitrators. Ellen, a female state employee, filed a sexual harassment grievance against her male supervisor and the state. Anne, the state''s attorney, exercised all of her five strikes to eliminate five of the female arbitrators. At the time she did so, Anne stated that she struck the five female arbitrators solely because she believed women, as a group, would necessarily be biased in favor of another woman who was claiming sexual harassment. Counsel for Ellen eliminated four males and one female arbitrator, all solely on grounds of specific bias or conflicts of interest. As a result, the panel was all male. When the panel ruled against Ellen on the merits of her case, she filed an action in an appropriate state court, challenging the panel selection process as a gender-based denial of equal protection of the laws. In this case, the court should hold that the panel selection process is', 'unconstitutional, because the gender classification used by the state''s attorney in this case does not satisfy the requirements of intermediate scrutiny.', 'unconstitutional, because the gender classification used by the state''s attorney in this case denies the grievant the right to a jury made up of her peers.', 'constitutional, because the gender classification used by the state''s attorney in this case satisfies the requirements of the strict scrutiny test.', 'constitutional, because the gender classification used by the state''s attorney in this case satisfies the requirements of the rational basis test.', 'A', 'To summarize the Court''s current directions for cases of official classification based on gender: Focusing on the differential treatment *533 for denial of opportunity for which relief is sought, the reviewing court must determine whether the proffered justification is “exceedingly persuasive.” The burden of justification is demanding and it rests entirely on the State. See Mississippi Univ. for Women, 458 U.S., at 724, 102 S.Ct., at 3336. The State must show “at least that the [challenged] classification serves ‘important governmental objectives and that the discriminatory means employed’ are ‘substantially related to the achievement of those objectives.’ ” Ibid. (quoting Wengler v. Druggists Mut. Ins. Co., 446 U.S. 142, 150, 100 S.Ct. 1540, 1545, 64 L.Ed.2d 107 (1980)). The justification must be genuine, not hypothesized or invented post hoc in response to litigation. And it must not rely on overbroad generalizations about the different talents, capacities, or preferences of males and females. See Weinberger v. Wiesenfeld, 420 U.S. 636, 643, 648, 95 S.Ct. 1225, 1230–1231, 1233, 43 L.Ed.2d 514 (1975); Califano v. Goldfarb, 430 U.S. 199, 223–224, 97 S.Ct. 1021, 1035–1036, 51 L.Ed.2d 270 (1977) (STEVENS, J., concurring in judgment).', 'mbe_893', 0, '180'),
('mbe_1174', 'mbe', '1174', '914', '1998', 'REAL PROP.', '181', '', 'Theresa owned Blueacre, a tract of land, in fee simple. Theresa wrote and executed, with the required formalities, a will that devised Blueacre to "my daughter, Della, for life with remainder to my descendants per stirpes." At the time of writing the will, Theresa had a husband and no descendants living other than her two children, Della and Seth. Theresa died and the will was duly admitted to probate. Theresa''s husband predeceased her. Theresa was survived by Della, Seth, four grandchildren, and one great-grandchild. Della and Seth were Theresa''s sole heirs at law. Della and Seth brought an appropriate action for declaratory judgment as to title of Blueacre. Guardians ad litem were appointed and all other steps were taken so that the judgment would bind all persons interested whether born or unborn. In that action, if the court rules that Della has a life estate in the whole of Blueacre and that the remainder is contingent, it will be because the court chose one of several possible constructions and that the chosen construction', 'related all vesting to the time of writing of the will.', 'related all vesting to the death of Theresa.', 'implied a condition that remaindermen survive Della.', 'implied a gift of a life estate to Seth.', 'C', 'A condition precedent is an event not certain to occur, but which must occur, before performance under a contract becomes due.  A condition precedent may be expressed in the parties'' agreement, implied in fact from the conduct of the parties, or implied in law (constructive) where the courts “construct” a condition for the purpose of attaining a just result. When there is a failure of a condition precedent through no fault of the parties, no liability or duty to perform arises under the contract. A condition precedent is distinguishable from a promise or covenant in that a condition creates no right or duty of performance in itself and its non-occurrence does not constitute a breach of the contract. A promise in a contract creates a legal duty in the promisor and a right in the promisee; the fact or event constituting a condition creates no right or duty and is merely a limiting or modifying factor. A covenant is a duty under the contract, the breach of which gives a right to enforce the contract.', 'mbe_894', 0, '181'),
('mbe_1175', 'mbe', '1175', '915', '1998', 'TORTS', '182', '', 'Driver negligently drove his car into Pedestrian, breaking her leg. Pedestrian''s leg was put in a cast, and she used crutches to get about. While shopping at Market, her local supermarket, Pedestrian nonnegligently placed one of her crutches on a banana peel that had been negligently left on the floor by the manager of Market''s produce department. Pedestrian''s crutch slipped on the peel, and she fell to the floor, breaking her arm. Had Pedestrian stepped on the banana peel at a time when she did not have to use crutches, she would have regained her balance. Pedestrian sued Driver and Market for her injuries. Pedestrian will be able to recover from', 'Driver, for her broken leg only.', 'Driver, for both of her injuries.', 'Market, for both of her injuries.', 'Driver, for her broken leg only, and Market, for her broken arm only.', 'B', 'The general rule is that a defendant is liable in damages to a plaintiff for all injuries proximately caused by his negligence. Dalton v. Gesser, 72 N.J.Super. 100, 178 A.2d 64 (1962); Pope v. Pinkerton-Hays Lumber Co., 120 So.2d 227 (Fla.App.1960); Menarde v. Philadelphia Transp. Co., 376 Pa. 497, 103 A.2d 681 (1954).  Then, where a defendant''s negligence causes injuries to a plaintiff and because of the weakened or impaired physical condition plaintiff suffers subsequent injuries, which are not brought about by the negligence of plaintiff, or any efficient intervening cause, defendant''s negligence is deemed to be the proximate cause of both the original and subsequent injuries. Hemmings v. Weinstein, 151 Conn. 502, 199 A.2d 687 (1964); Pope v. Pinkerton-Hays Lumber Co., supra; **201 Lester v. Hennessey, 20 Ill.App.2d 479, 156 N.E.2d 247 (1959); Squires v. Reynolds, 125 Conn. 366, 5 A.2d 877 (1939); Stahl v. So. Michigan Ry., 211 Mich. 350, 178 N.W. 710 (1920); Hartnett v. Tripp, 231 Mass. 382, 121 N.E. 17 (1918).', 'mbe_895', 0, '182'),
('mbe_1176', 'mbe', '1176', '916', '1998', 'CRIM. LAW', '183', '', 'FBI agents, without a warrant and without permission of Mexican law enforcement or judicial officers, entered Mexico, kidnapped Steven, an American citizen wanted in the United States for drug smuggling violations, and forcibly drove him back to Texas. Thereafter, the agents, again without a warrant, broke into the Texas home of Joan, wanted as a confederate of Steven, and arrested her. Steven and Joan were both indicted for narcotics violations. Both moved to dismiss the indictment on the ground that their arrests violated the Fourth Amendment. The court should', 'grant the motions of both Steven and Joan.', 'grant the motion of Steven and deny the motion of Joan.', 'grant the motion of Joan and deny the motion of Steven.', 'deny the motions of both Steven and Joan.', 'D', 'A warrantless arrest does not violate the Fourth Amendment if it is supported by probable cause.5 See U.S. Const. amend. IV; United States v. Watson, 423 U.S. 411, 414-15, 96 S.Ct. 820, 46 L.Ed.2d 598 (1976). Probable cause exists when the totality of the circumstances shows that a prudent person would believe that the arrested has committed a crime. See Illinois v. Gates, 462 U.S. 213, 238-39, 103 S.Ct. 2317, 76 L.Ed.2d 527 (1983). In determining whether an officer had probable cause, a court must “examine the events leading up to the arrest, and then decide whether the facts, viewed from the standpoint of an objectively reasonable ... officer amount to probable cause.” Maryland v. Pringle, 540 U.S. 366, 370, 124 S.Ct. 795, 157 L.Ed.2d 769 (2003) (internal quotations and citation omitted). So long as probable cause for one crime exists, whether the officers had probable cause to arrest for other offenses is immaterial. Smithson v. Aldrich, 235 F.3d 1058, 1062 (8th Cir. 2000). And even when, with the benefit of hindsight, a law enforcement officer lacks probable cause to make an arrest, the officer is entitled to qualified immunity if he has “arguable” probable cause—that is, if he reasonably (but wrongly) believes probable cause exists. Amrine v. Brooks, 522 F.3d 823, 832 (8th Cir. 2008).', 'mbe_896', 0, '183'),
('mbe_1177', 'mbe', '1177', '917', '1998', 'CONTRACTS', '184', '', 'Gourmet purchased the front portion of the land needed for a restaurant he desired to build and operate, but the back portion was the subject of a will dispute between Hope and Faith (two sisters). Hope''s attorney advised her that her claim was doubtful. Gourmet, knowing only that the unresolved dispute existed, agreed in a signed writing to pay Hope $6,000, payable $1,000 annually, in exchange for a quitclaim deed (a deed containing no warranties) from Hope, who promptly executed such a deed to Gourmet and received Gourmet''s first annual payment. Shortly thereafter, the probate court handed down a decision in Faith''s favor, ruling that Hope had no interest in the land. This decision has become final. Gourmet subsequently defaulted when his second annual installment came due. In an action against Gourmet for breach of contract, Hope will probably', 'lose, because she was aware at the time of the agreement with Gourmet that her claim to the property quitclaimed was doubtful.', 'lose, because Hope suffered no legal detriment in executing the quitclaim deed.', 'win, because Gourmet bargained for and received in exchange a quitclaim deed from Hope.', 'win, because Gourmet, by paying the first $1,000 installment, is estopped to deny that his agreement with Hope is an enforceable contract.', 'C', '“It is a well-established principle that a valid contract requires ‘competent parties, subject matter, a legal consideration, mutuality of agreement, and mutuality of obligation.’ ” Voccola v. Forte, 139 A.3d 404, 414 (R.I. 2016) (quoting DeLuca v. City of Cranston, 22 A.3d 382, 384 (R.I. 2011) (mem.)). “[C]onsideration ‘consists of some legal right acquired by the promisor in consideration of his promise, or forborne by the promisee in consideration of such promise.’ ” DeLuca, 22 A.3d at 384 (quoting DeAngelis v. DeAngelis, 923 A.2d 1274, 1279 (R.I. 2007)). “When evaluating the sufficiency of contractual consideration, we employ ‘the bargained-for exchange test.’ ” Id. (quoting DeAngelis, 923 A.2d at 1279). That test “provides that something is bargained for, * * * if it is sought by the promisor in exchange for his [or her] promise and is given by the promisee in exchange for that promise.” Id. (quoting DeAngelis, 923 A.2d at 1279).', 'mbe_179', 0, '184'),
('mbe_1178', 'mbe', '1178', '918', '1998', 'TORTS', '185', '', 'Athlete, a professional football player, signed a written consent for his team''s physician, Doctor, to perform a knee operation. After Athlete was under a general anesthetic, Doctor asked Surgeon, a world famous orthopedic surgeon, to perform the operation. Surgeon''s skills were superior to Doctor''s, and the operation was successful. In an action for battery by Athlete against Surgeon, Athlete will', 'prevail, because Athlete did not agree to allow Surgeon to perform the operation.', 'prevail, because the consent form was in writing.', 'not prevail, because Surgeon''s skills were superior to Doctor''s.', 'not prevail, because the operation was successful.', 'A', 'Battery is defined as “the unprivileged touching or striking of one person by another, done with the intent of bringing about either a contact or an apprehension of contact, that is harmful or offensive.” PIK Civ.3d 127.02; see Laurent, 1 Kan. at *431. The gravamen of a civil assault and battery is grounded upon the actor''s intention to inflict injury. Stricklin v. Parsons Stockyard Co., 192 Kan. 360, 366, 388 P.2d 824 (1964).', 'mbe_214', 0, '185')
ON CONFLICT (idx) DO NOTHING;
